// Calculate supplier reliability scores based on purchase order history
// Group by product_code and supplier_id, calculate fulfillment rate

const items = $input.all();

// Extract purchase orders from the merged data
const purchaseOrders = [];
for (const item of items) {
  if (item.json.purchase_orders) {
    purchaseOrders.push(...item.json.purchase_orders);
  }
}

// Group by product_code and supplier_id
const supplierStats = {};

for (const po of purchaseOrders) {
  const key = `${po.product_code}_${po.supplier_id}`;

  if (!supplierStats[key]) {
    supplierStats[key] = {
      product_code: po.product_code,
      supplier_id: po.supplier_id,
      totalOrdered: 0,
      totalReceived: 0
    };
  }

  supplierStats[key].totalOrdered += po.ordered_qty || 0;
  supplierStats[key].totalReceived += po.received_qty || 0;
}

// Calculate fulfillment rates and flag unreliable suppliers
const supplierReliability = {};

for (const key in supplierStats) {
  const stats = supplierStats[key];
  const fulfillmentRate = stats.totalOrdered > 0 
    ? stats.totalReceived / stats.totalOrdered 
    : 1.0;

  const productSupplierKey = `${stats.product_code}_${stats.supplier_id}`;
  supplierReliability[productSupplierKey] = {
    supplierReliabilityScore: fulfillmentRate,
    isUnreliableSupplier: fulfillmentRate < 0.85
  };
}

// Add supplier reliability fields to each item
const enrichedItems = items.map(item => {
  const productCode = item.json.product_code || item.json.ProductCode;
  const supplierId = item.json.supplier_id || item.json.SupplierId;

  const key = `${productCode}_${supplierId}`;
  const reliability = supplierReliability[key] || {
    supplierReliabilityScore: 1.0,
    isUnreliableSupplier: false
  };

  return {
    json: {
      ...item.json,
      supplierReliabilityScore: reliability.supplierReliabilityScore,
      isUnreliableSupplier: reliability.isUnreliableSupplier
    }
  };
});

return enrichedItems;

// Prepare features for Vertex AI Model
// Extract and transform data from merged sources into ML-ready format

const items = $input.all();
const instances = [];

// Helper function to check if date is a holiday (Finnish holidays)
function isHoliday(date) {
  const holidays = [
    '01-01', '01-06', '05-01', '12-06', '12-24', '12-25', '12-26'
  ];
  const monthDay = date.toFormat('MM-dd');
  return holidays.includes(monthDay);
}

for (const item of items) {
  const json = item.json;

  // Extract basic features
  const orderedQty = json.ordered_qty || 0;
  const inventoryLevel = json.inventory_level || 0;
  const supplierReliabilityScore = json.supplierReliabilityScore || 0.5;

  // Calculate seasonality indicators
  const currentDate = $now;
  const dayOfWeek = currentDate.weekday; // 1=Monday, 7=Sunday
  const month = currentDate.month; // 1-12
  const isHolidayFlag = isHoliday(currentDate) ? 1 : 0;

  // Extract shelf life from product data
  const shelfLife = json.shelf_life || json.product_shelf_life || 365;

  // Count quality incidents from replacement orders
  const qualityIncidents = json.quality_incidents_count || 0;

  // Calculate pick time window pressure
  // Higher value = more pressure (less time available)
  const currentHour = currentDate.hour;
  const pickingEndHour = 14; // 14:00 Finnish time
  const hoursRemaining = Math.max(0, pickingEndHour - currentHour);
  const pickTimeWindowPressure = hoursRemaining > 0 ? (1 / hoursRemaining) : 1;

  // Build feature instance for Vertex AI
  const instance = {
    ordered_qty: orderedQty,
    inventory_level: inventoryLevel,
    supplier_reliability_score: supplierReliabilityScore,
    day_of_week: dayOfWeek,
    month: month,
    is_holiday: isHolidayFlag,
    shelf_life: shelfLife,
    quality_incidents: qualityIncidents,
    pick_time_window_pressure: pickTimeWindowPressure,
    // Include identifiers for tracking
    product_id: json.product_id || json.material_number,
    order_id: json.order_id || json.sales_order
  };

  instances.push(instance);
}

// Format for Vertex AI Prediction API
const vertexAIPayload = {
  instances: instances
};

return [{ json: vertexAIPayload }];

// Parse Vertex AI response and flag anomalies
const item = $input.item.json;

// Extract prediction from Vertex AI response
const predictions = item.predictions || [];
let stockOutProbability = 0;
let confidenceScore = 0;

// Parse the prediction array (assuming first prediction contains our values)
if (predictions.length > 0) {
  const prediction = predictions[0];

  // Extract stock-out probability and confidence
  // Adjust these field names based on your actual Vertex AI model output
  stockOutProbability = prediction.stockOutProbability || prediction.probability || 0;
  confidenceScore = prediction.confidence || prediction.confidenceScore || 0;
}

// Apply supplier penalty if supplier is unreliable
const supplierReliabilityScore = item.supplierReliabilityScore || 1.0;
if (supplierReliabilityScore < 0.7) {
  stockOutProbability += 0.15;
  // Cap at 1.0
  stockOutProbability = Math.min(stockOutProbability, 1.0);
}

// Calculate final risk level
let riskLevel = 'LOW';
let needsSubstitution = false;

if (stockOutProbability > 0.6) {
  riskLevel = 'HIGH';
  needsSubstitution = true;
} else if (stockOutProbability > 0.3) {
  riskLevel = 'MEDIUM';
  needsSubstitution = true;
}

// Return enriched item with risk assessment
return {
  ...item,
  stockOutProbability: stockOutProbability,
  confidenceScore: confidenceScore,
  riskLevel: riskLevel,
  needsSubstitution: needsSubstitution
};

// Score and Rank Substitution Candidates
// This code processes substitute products from Zilliz vector DB and ranks them

const item = $input.item.json;

// Extract substitute candidates from vector DB response
const substitutes = item.substitutes || [];
const originalProduct = item.original_product || {};
const customerPreferences = item.customer_preferences || {};
const customerAllergens = item.customer_allergens || [];

// Helper function: Calculate cosine similarity between two nutrition vectors
function cosineSimilarity(vecA, vecB) {
  if (!vecA || !vecB) return 0;

  const keys = Object.keys(vecA);
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;

  keys.forEach(key => {
    const a = vecA[key] || 0;
    const b = vecB[key] || 0;
    dotProduct += a * b;
    normA += a * a;
    normB += b * b;
  });

  if (normA === 0 || normB === 0) return 0;
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

// Helper function: Calculate price delta percentage
function calculatePriceDelta(originalPrice, substitutePrice) {
  if (!originalPrice || originalPrice === 0) return 0;
  return ((substitutePrice - originalPrice) / originalPrice) * 100;
}

// Helper function: Check allergen compatibility
function isAllergenCompatible(productAllergens, customerAllergens) {
  if (!customerAllergens || customerAllergens.length === 0) return true;
  if (!productAllergens || productAllergens.length === 0) return true;

  return !productAllergens.some(allergen => 
    customerAllergens.includes(allergen)
  );
}

// Helper function: Check customer preference history
function getPreferenceScore(productId, preferences) {
  if (!preferences || !preferences.purchased_products) return 0;

  const purchaseHistory = preferences.purchased_products || [];
  const purchaseCount = purchaseHistory.filter(p => p === productId).length;

  // Normalize to 0-1 scale (assuming max 10 purchases)
  return Math.min(purchaseCount / 10, 1);
}

// Score each substitute
const scoredSubstitutes = substitutes.map(substitute => {
  // 1. Nutritional similarity score (0-1)
  const nutritionScore = cosineSimilarity(
    originalProduct.nutrition || {},
    substitute.nutrition || {}
  );

  // 2. Price delta percentage
  const priceDelta = calculatePriceDelta(
    originalProduct.price || 0,
    substitute.price || 0
  );

  // Price score: prefer similar or lower prices (0-1)
  const priceScore = priceDelta <= 0 ? 1 : Math.max(0, 1 - (priceDelta / 50));

  // 3. Customer preference score (0-1)
  const preferenceScore = getPreferenceScore(
    substitute.product_id,
    customerPreferences
  );

  // 4. Allergen compatibility (boolean)
  const allergenCompatible = isAllergenCompatible(
    substitute.allergens || [],
    customerAllergens
  );

  // 5. Availability score (0-1)
  const availabilityScore = substitute.stock_level > 0 ? 
    Math.min(substitute.stock_level / 100, 1) : 0;

  // Calculate combined score (weighted average)
  // Weights: nutrition 30%, price 25%, preference 20%, availability 25%
  const combinedScore = allergenCompatible ? 
    (nutritionScore * 0.30 + 
     priceScore * 0.25 + 
     preferenceScore * 0.20 + 
     availabilityScore * 0.25) : 0;

  return {
    ...substitute,
    scores: {
      nutrition: Math.round(nutritionScore * 100) / 100,
      price: Math.round(priceScore * 100) / 100,
      preference: Math.round(preferenceScore * 100) / 100,
      availability: Math.round(availabilityScore * 100) / 100,
      combined: Math.round(combinedScore * 100) / 100
    },
    price_delta_percent: Math.round(priceDelta * 100) / 100,
    allergen_compatible: allergenCompatible
  };
});

// Filter by allergen compatibility and availability
const validSubstitutes = scoredSubstitutes.filter(s => 
  s.allergen_compatible && s.scores.availability > 0
);

// Sort by combined score (descending)
validSubstitutes.sort((a, b) => b.scores.combined - a.scores.combined);

// Take top 3 and assign ranking
const top3Substitutes = validSubstitutes.slice(0, 3).map((substitute, index) => {
  let ranking;
  if (index === 0) ranking = 'best';
  else if (index === 1) ranking = 'better';
  else ranking = 'good';

  return {
    ...substitute,
    ranking,
    rank_position: index + 1
  };
});

// Return enriched item with ranked substitutes
return {
  json: {
    ...item,
    ranked_substitutes: top3Substitutes,
    substitutes_found: top3Substitutes.length,
    original_product: originalProduct
  }
};
